class Solution {
public:
    int minNumberOfFrogs(string croakOfFrogs) {
        int cnt[5] = {0, 0, 0, 0, 0};
        string s = "croak";
        int frogs = 0, ans = 0;
        for (char ch : croakOfFrogs) {
            int idx = (int)s.find(ch);
            if (idx == 0) {
                if (cnt[4] > 0) cnt[4]--;
                cnt[0]++;
                frogs++;
                if (frogs > ans) ans = frogs;
            } else {
                if (cnt[idx - 1] == 0) return -1;
                cnt[idx - 1]--;
                cnt[idx]++;
                if (idx == 4) frogs--;
            }
        }
        return frogs == 0 ? ans : -1;
    }
};
